            d += datetime.timedelta(days=1)
    except Exception:
        pass
    return None

def resolve_date_expr(today, expr, calendar):
    try:
        d = _date(today)
        if d is None or not isinstance(expr, dict) or (not isinstance(calendar, dict)):
