def _fresh_state():
    S = dict()
    parsed = parse_now(_get('now')) if 'parse_now' in globals() else None
    parsed = parsed or (None, None)
    S['today'] = parsed[0] or _get('now')[:10]
    S['now_time'] = parsed[1] or _get('now')[11:16]
