WEEKDAYS = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday']

def _str(x):
    return '' if x is None else str(x)

def _S():
    try:
        s = json.loads(_str(vars.get('state_json')) or '{}')
        if not isinstance(s, dict):
            s = dict()
    except Exception:
        s = dict()
    if 'today' not in s:
