        v[stage] = int(v.get(stage, 0)) + 1
        S['visits'] = v
        _save(S)
        if v[stage] > 30 and stage in ('opening_route', 'cb_route', 'neg_route', 'readback_route') or (stage.startswith('id_route_') and v[stage] > 30):
